package studio.jiayu.neoagent;
final class AppCatalog {static boolean isCommerce(String pkg){return pkg.equals("cn.damai")||pkg.equals("com.taobao.taobao")||pkg.equals("com.jingdong.app.mall")||pkg.equals("com.xunmeng.pinduoduo")||pkg.equals("com.sankuai.meituan")||pkg.equals("com.sankuai.meituan.takeoutnew")||pkg.equals("me.ele");}}
